import { Catalog, Category, ErrorEvent, Identity, PartyIdentification, UserEngagement } from '../events';
/**
Description: The interaction where a generic form is submitted. If there is a more specific interaction associated to a form submission that applies it should be sent instead.
*/
export type SubmitForm = {
    events: Array<UserEngagement | Catalog | Identity | PartyIdentification | ErrorEvent>;
}

export class SubmitFormBuilder {

    private submitForm: SubmitForm = {
        events: []
    }

    private catalog!: Catalog;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;
    private userEngagement!: UserEngagement;

    public withCatalog(catalog: Catalog) : SubmitFormBuilder {
        this.catalog = catalog;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : SubmitFormBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : SubmitFormBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : SubmitFormBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }
    public withUserEngagement(userEngagement: UserEngagement) : SubmitFormBuilder {
        this.userEngagement = userEngagement;
        return this;
    }

    public build() : SubmitForm {
        if(this.catalog) {
            this.submitForm.events.push(this.catalog);
        }
        if(this.errorEvent) {
            this.submitForm.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.submitForm.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.submitForm.events.push(this.partyIdentification);
        }
        if(this.userEngagement) {
            this.submitForm.events.push(this.userEngagement);
        }

        return this.submitForm;
    }
}
